CDEC$ IDENT 'OTHER'
      SUBROUTINE OTHER
      COMMON /PAGED/ X /LOCAL/ L /FIXED/ K
      INTEGER L, K
CDEC$ PSECT /PAGED/ ALIGN=9
CDEC$ PSECT /LOCAL/ LCL, NOSHR
CDEC$ PSECT /FIXED/ NOWRT
      PRINT *, 'OTHER', MOD(%LOC(X), 512), X, L, K
      X = X + 1.0
      L = L + 1
      END

      BLOCK DATA START
      COMMON /FIXED/ K
      INTEGER K
CDEC$ PSECT /FIXED/ NOWRT
      DATA K /77/
      END
